-- Inserción de costos de rutas
INSERT INTO `lgs_costos_rutas` (`id_tipo_traslado`, `id_origen`, `id_destino`, `id_segmento`, `num_vins_min`, `num_vins_max`, `km`, `costo_por_km`, `precio_plano`, `factor`, `activo`)
SELECT 1, o.id_origen, d.id_destino, 1, 1, 15, 0, 0, 0, 1, 2
FROM `lgs_cat_origenes` o
JOIN `lgs_cat_destinos` d
WHERE o.nombre = '' AND d.nombre = ''
ON DUPLICATE KEY UPDATE `km` = VALUES(`km`), `costo_por_km` = VALUES(`costo_por_km`), `precio_plano` = VALUES(`precio_plano`), `factor` = VALUES(`factor`), `activo` = 2;
